// @generated by:gauntlet run:godseye-hermes-setup
import { execFile } from "node:child_process";
import { resolve } from "node:path";
import { promisify } from "node:util";
import { describe, expect, it } from "vitest";

const execute = promisify(execFile);
const enabled = process.env.GODSEYE_HERMES_LAB === "enabled";
const windows = process.platform === "win32";
const distro = process.env.GODSEYE_HERMES_WSL_DISTRO ?? "Ubuntu";

describe.runIf(enabled)("actual pinned local Hermes without provider or model access", () => {
  it("T-AC-702 imports pinned Hermes, Python and OpenAI SDK with network denied", async () => {
    const result = await execute(
      process.execPath,
      [resolve("scripts/install-hermes.mjs"), "smoke"],
      {
        windowsHide: true,
        timeout: 180000,
      },
    );
    const report = JSON.parse(result.stdout) as {
      version: string;
      commit: string;
      status: string;
      smoke: { hermesVersion: string; pythonVersion: string; modelCalls: number; network: string };
    };
    expect(report.version).toBe("0.23.1");
    expect(report.commit).toBe("3b421578588243f920886e6fe79a6faa87ea026e");
    expect(report.status).toBe("installed");
    expect(report.smoke.hermesVersion).toBe(report.version);
    expect(report.smoke.pythonVersion).toBe("3.14.9");
    expect(report.smoke.network).toBe("denied");
    expect(report.smoke.modelCalls).toBe(0);
  }, 190000);

  it("T-AC-702 T-AC-705 resolves all three generated configurations in disposable mutable homes with one pinned skill and zero tools", async () => {
    const helper = resolve("tests/helpers/hermes-native.py");
    const path = windows
      ? (
          await execute("wsl", ["-d", distro, "--exec", "wslpath", "-u", helper], {
            windowsHide: true,
            timeout: 15000,
          })
        ).stdout.trim()
      : helper;
    const args = [
      "-B",
      path,
      "RealHermes.test_generated_profiles_resolve_only_pinned_skills_and_zero_tools",
    ];
    const result = await execute(
      windows ? "wsl" : "python3",
      windows ? ["-d", distro, "--exec", "python3", ...args] : args,
      { windowsHide: true, timeout: 180000 },
    );
    expect(result.stderr).toMatch(/Ran 1 test/);
    expect(result.stderr).toMatch(/\bOK\b/);
  }, 190000);
});
